import math
    import random
    import time

    LANGUAGE_WRAPPER = 'A set of positive integers has the {gon_order}-gon property if it contains {gon_order} distinct elements that can be the side lengths of a nondegenerate {gon_order}-gon; equivalently, among those {gon_order} elements, the largest is strictly less than the sum of the other {gon_order}-1. Consider the consecutive-integer set {start}, {start}+1, ..., n. Determine the largest integer n such that every {subset_size}-element subset of this set has the {gon_order}-gon property.'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate parameters for the generalized problem:
# start = m >= 3, gon_order = p in {3,4,5}, subset_size = t >= p+6.
# The answer is a_t - 1 where (a_k) is the order-(p-1) minimal sum-sequence
# with seeds a_1 = m, a_2 = m+1, ..., a_{p-1} = m+p-2 and a_k = sum of previous (p-1) terms.
def compute_answer(m, p, t):
    L = p - 1
    seq = [m + i for i in range(L)]
    while len(seq) < t:
        seq.append(sum(seq[-L:]))
    return seq[-1] - 1
# Try a few times to get a nontrivial instance
for _ in range(100):
    p = rng.choice([3, 4, 5])
    m = rng.randint(3, 10)
    t = rng.randint(p + 6, p + 12)  # ensure reasonably large t
    ans = compute_answer(m, p, t)
    # difficulty and practicality constraints
    if ans >= m + 50 and ans <= 10**7:
        return {
            'start': m,
            'subset_size': t,
            'gon_order': p
        }
# As a fallback, enforce p=4 and increase t for growth
p = 4
m = 6
t = 12
ans = compute_answer(m, p, t)
return {
    'start': m,
    'subset_size': t,
    'gon_order': p
}

    def verifier(assign):
# Verify parameters and compute the unique correct answer.
# The largest n such that every t-element subset of {m, m+1, ..., n} has the p-gon property
# equals a_t - 1, where (a_k) is the minimal order-(p-1) sum-sequence:
# seeds a_1 = m, a_2 = m+1, ..., a_{p-1} = m+p-2, and for k >= p, a_k = sum_{j=1}^{p-1} a_{k-j}.
# Proof sketch (comments):
# Necessity: If a sorted t-subset S = {a_1 < ... < a_t} fails the p-gon property, then for each k >= p,
# the p-tuple {a_{k-(p-1)}, ..., a_{k-1}, a_k} must violate the polygon inequality, so a_k >= sum of the previous (p-1).
# Thus every bad subset obeys this recurrence, implying its maximum >= the minimal a_t built by equality.
# Sufficiency: The constructed sequence with equality has every consecutive p-block violating the polygon inequality,
# hence is a bad subset inside {m, ..., a_t}. Therefore, all t-subsets of {m, ..., n} have the property iff n < a_t,
# giving the largest valid n as a_t - 1.
try:
    m = int(assign.get('start', None))
    t = int(assign.get('subset_size', None))
    p = int(assign.get('gon_order', None))
except Exception:
    # Invalid types
    return (False, None)
# Domain checks
if m is None or t is None or p is None:
    # Missing keys
    return (False, None)
if not (isinstance(m, int) and isinstance(t, int) and isinstance(p, int)):
    # Non-integer inputs
    return (False, None)
if p < 3:
    # Polygon must have at least 3 sides
    return (False, None)
if t < p + 6:
    # Enforce difficulty: require many steps beyond trivial p
    return (False, None)
if m < 3:
    # Enforce m >= 3 for nontrivial growth and to avoid tiny starts
    return (False, None)
# Compute a_t
L = p - 1
# Seeds are consecutive: m, m+1, ..., m+L-1
seq = [m + i for i in range(L)]
# Build up to t
while len(seq) < t:
    # Sum of previous L terms
    s = 0
    for x in seq[-L:]:
        s += x
    seq.append(s)
a_t = seq[-1]
answer = a_t - 1
# Additional difficulty checks to avoid trivial small outputs
if answer < m + 50:
    # Interval too short; problem may be trivial
    return (False, None)
if answer > 10**7:
    # Keep numbers within practical bounds for contest settings
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

